#!/usr/bin/env bash
# Writes deploy/compose/.env with random, local-only secrets (never overwrites an existing file).
set -euo pipefail
out="$(dirname "$0")/../deploy/compose/.env"
[ -f "$out" ] && { echo "keeping existing $out"; exit 0; }
rnd() { LC_ALL=C tr -dc 'A-Za-z0-9' </dev/urandom | head -c "$1"; }
cat >"$out" <<ENV
# Generated by scripts/gen-local-env.sh. Local-only secrets: never reuse them elsewhere.
TP_API_KEY_PEPPER=$(rnd 40)
TP_BOOTSTRAP_API_KEY=tp_local$(rnd 2 | tr 'A-Z' 'a-z' | head -c 2)01_$(rnd 28)
ENV
echo "wrote $out"
